#!/usr/bin/env node
const fs = require('fs-extra');

var outputDefinePath = ".vscode/robloxLibs/_gen"
var outputRobloxManifest = "build/_robloxManifest"


var writeLuaConfigs = require('./write-lua-configs');
var writeLuaDefinesConfigs = require('./write-lua-defines-configs');
var parseConfigs = require('./parse-configs');
const { exit } = require('process');



var robloxPathDict = require('./get-rojo-path');
var rojoConfigPath = process.argv[2]
robloxPathDict.init(rojoConfigPath)

var folders = process.argv.slice(3)

// watch main folders
var watcher = require('./watcher');
watcher.watchFiles(folders);


function writeFiles() {
    writeLuaDefinesConfigs(parseConfigs.GetLuaConfigs(), outputDefinePath)
    writeLuaConfigs(parseConfigs.GetLuaConfigs(), outputRobloxManifest)
}

function init() {


    parseConfigs.Init({ robloxPathDict })
    parseConfigs.TryGen(folders);


    writeFiles()
}

var states = {}
var curKey = 0

function onWatchUpdate(events) {
    curKey = 0
    // 从 ignorePaths 中排除 events
    // 从 events 中过滤掉 ignoreFiles 中的文件
    events = Object.keys(events).reduce((filteredEvents, eventPath) => {
        if (!ignoreFiles.some(ignoreFile => eventPath.endsWith(ignoreFile))) {
            filteredEvents[eventPath] = events[eventPath];
        }
        return filteredEvents;
    }, {});


    if (parseConfigs.TryGenOnUpdate(events)) {
        writeLuaDefinesConfigs(parseConfigs.GetLuaConfigs(), outputDefinePath)
        writeLuaConfigs(parseConfigs.GetLuaConfigs(), outputRobloxManifest)
        curKey++
    }
}


function wrapWatchUpdate(events, handler) {
    try {
        handler(events)
        // print if all in states is true
        if (Object.values(states).every(state => state)) {
            console.log("success write files")
        }
    } catch (e) {
        states[curKey] = false
        console.error("TangSeng Error:" + e.message)
        throw (e)
    }
}




watcher.registerEventCallback(function (events) {
    wrapWatchUpdate(events, onWatchUpdate)
});


try {
    init()
    console.log("success write files")
} catch (e) {
    throw e
    console.error("TangSeng Error:" + e.message)
    exit(0)
}